import { ADD, Del } from "../types";

const initalState = {
task: [],
};

const taskReducer = (state = initalState, action) => {
switch (action.type) {
    case ADD:
    return {
        ...state,
        task: [
        ...state.task,
        {
            id: new Date().getTime(),
            task: action.payload,
            date: `${new Date().getFullYear()} / ${
            new Date().getMonth() + 1
            } / ${new Date().getDate()}`,
            checked: false,
        },
        ],
    };
    case Del:
    return {
        ...state,
        // task: state.task.filter((elm)=> elm.id !== action.payload)
    }

    default:
    return state;
}
};

export default taskReducer;
